// CSP配置
// HTTP头
// Content-Security-Policy: default-src 'self'; script-src 'self' 'nonce-xxx' https://cdn.com; style-src 'self' 'unsafe-inline'

// HTML meta标签
// <meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'self'">

// Express CSP中间件
const helmet = require('helmet');
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'", "'nonce-xxx'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", 'data:', 'https:'],
    connectSrc: ["'self'", 'https://api.example.com']
  }
}));

// CSRF防护：SameSite Cookie
// Set-Cookie: token=xxx; SameSite=Lax; Secure; HttpOnly

// CSRF Token
// 服务端生成token，前端在请求头中携带
const csrfToken = document.querySelector('meta[name=csrf-token]').content;
fetch('/api/transfer', {
  method: 'POST',
  headers: {
    'X-CSRF-Token': csrfToken
  },
  body: JSON.stringify({ amount: 100 })
});

